program='''def transform(grid):
    g=[r[:] for r in grid]
    # Locate the framed workspace.
    pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==5]
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    out=[row[c0:c1+1] for row in g[r0:r1+1]]
    bg=g[0][4]
    # Keys are 3x3 copies of 110/111/110, with their output color at right.
    keys={}
    for r in range(r0-2):
        for c in range(c1-2):
            col=g[r][c]
            pat=[[g[r+i][c+j]==col for j in range(3)] for i in range(3)]
            if pat==[[1,1,0],[1,1,1],[1,1,0]] and g[r][c+3]!=bg:
                keys[col]=g[r][c+3]
    # Find each key's 3x3 target miniature outside the workspace.
    rules={}
    for col,newcol in keys.items():
        for r in range(r0-2):
            for c in range(c1-2):
                counts=sum(g[r+i][c+j]==col for i in range(3) for j in range(3))
                if counts and not (g[r][c]==col and g[r][c+1]==col and g[r+1][c+2]==col):
                    # Exclude the key shape itself.
                    pat=[[g[r+i][c+j]==col for j in range(3)] for i in range(3)]
                    if pat!=[[1,1,0],[1,1,1],[1,1,0]]:
                        rules[col]=(newcol,pat)
    # Replace each solid monochrome rectangle by its tiled target pattern.
    for r in range(1,len(out)-1):
        for c in range(1,len(out[0])-1):
            col=out[r][c]
            if col not in rules: continue
            rr=r
            while rr<len(out)-1 and out[rr][c]==col: rr+=1
            cc=c
            while cc<len(out[0])-1 and out[r][cc]==col: cc+=1
            if rr-r>=3 and cc-c>=3 and all(out[i][j]==col for i in range(r,rr) for j in range(c,cc)):
                newcol,pat=rules[col]
                for i in range(r,rr):
                    for j in range(c,cc): out[i][j]=newcol if pat[(i-r)%3][(j-c)%3] else bg
    return out
'''
